UPDATE UTIL.tmp_IDW_LAKE_TRIGGERS_CHECK_CONTROL
SET IDW_LAKE_TRIGGERS_CHECK_CONTROL_KEY = UTIL.FXN_ARRAY_HASH([ADF_PIPELINE_NAME])
;

-- Use a minus query to find any diffs and update or insert as needed
MERGE INTO UTIL.IDW_LAKE_TRIGGERS_CHECK_CONTROL AS TGT

USING (SELECT IDW_LAKE_TRIGGERS_CHECK_CONTROL_KEY, IS_ACTIVE, ADF_PIPELINE_NAME, CONTROL_TABLE_DATABASE, CONTROL_TABLE_SCHEMA, CONTROL_TABLE_NAME, CONTROL_TABLE_TRIGGER_COLUMN_NAME, IS_PARTITION_BY_STRING_COLUMN_NAME, IS_PARTITION_BY_STRING_VALUE, IS_PARTITION_BY_DATE_COLUMN_NAME, IS_PARTITION_BY_DATE_VALUE, ORACLE_META_TABLE, META_TABLE_SCHEMA_COLUMN, IS_DEPT_PIPELINE, TARGET_STORAGE_CONTAINER
    FROM UTIL.tmp_IDW_LAKE_TRIGGERS_CHECK_CONTROL
    MINUS
    SELECT IDW_LAKE_TRIGGERS_CHECK_CONTROL_KEY, IS_ACTIVE, ADF_PIPELINE_NAME, CONTROL_TABLE_DATABASE, CONTROL_TABLE_SCHEMA, CONTROL_TABLE_NAME, CONTROL_TABLE_TRIGGER_COLUMN_NAME, IS_PARTITION_BY_STRING_COLUMN_NAME, IS_PARTITION_BY_STRING_VALUE, IS_PARTITION_BY_DATE_COLUMN_NAME, IS_PARTITION_BY_DATE_VALUE, ORACLE_META_TABLE, META_TABLE_SCHEMA_COLUMN, IS_DEPT_PIPELINE, TARGET_STORAGE_CONTAINER
    FROM UTIL.IDW_LAKE_TRIGGERS_CHECK_CONTROL)
    AS SRC

ON (
    TGT.ADF_PIPELINE_NAME = SRC.ADF_PIPELINE_NAME
    )

WHEN MATCHED
THEN UPDATE
    SET TGT.IDW_LAKE_TRIGGERS_CHECK_CONTROL_KEY = SRC.IDW_LAKE_TRIGGERS_CHECK_CONTROL_KEY,
    TGT.IS_ACTIVE = SRC.IS_ACTIVE,
    TGT.LAST_UPDATED_DATETIME = CURRENT_TIMESTAMP(),
    TGT.ADF_PIPELINE_NAME = SRC.ADF_PIPELINE_NAME,
    TGT.CONTROL_TABLE_DATABASE = SRC.CONTROL_TABLE_DATABASE,
    TGT.CONTROL_TABLE_SCHEMA = SRC.CONTROL_TABLE_SCHEMA,
    TGT.CONTROL_TABLE_NAME = SRC.CONTROL_TABLE_NAME,
    TGT.CONTROL_TABLE_TRIGGER_COLUMN_NAME = SRC.CONTROL_TABLE_TRIGGER_COLUMN_NAME,
    TGT.IS_PARTITION_BY_STRING_COLUMN_NAME = SRC.IS_PARTITION_BY_STRING_COLUMN_NAME,
    TGT.IS_PARTITION_BY_STRING_VALUE = SRC.IS_PARTITION_BY_STRING_VALUE,
    TGT.IS_PARTITION_BY_DATE_COLUMN_NAME = SRC.IS_PARTITION_BY_DATE_COLUMN_NAME,
    TGT.IS_PARTITION_BY_DATE_VALUE = SRC.IS_PARTITION_BY_DATE_VALUE,
    TGT.ORACLE_META_TABLE = SRC.ORACLE_META_TABLE,
    TGT.META_TABLE_SCHEMA_COLUMN = SRC.META_TABLE_SCHEMA_COLUMN,
    TGT.IS_DEPT_PIPELINE = SRC.IS_DEPT_PIPELINE,
    TGT.TARGET_STORAGE_CONTAINER = SRC.TARGET_STORAGE_CONTAINER
WHEN NOT MATCHED
THEN INSERT
    (IDW_LAKE_TRIGGERS_CHECK_CONTROL_KEY, IS_ACTIVE, INSERT_DATETIME, LAST_UPDATED_DATETIME, ADF_PIPELINE_NAME, CONTROL_TABLE_DATABASE, CONTROL_TABLE_SCHEMA, CONTROL_TABLE_NAME, CONTROL_TABLE_TRIGGER_COLUMN_NAME, IS_PARTITION_BY_STRING_COLUMN_NAME, IS_PARTITION_BY_STRING_VALUE, IS_PARTITION_BY_DATE_COLUMN_NAME, IS_PARTITION_BY_DATE_VALUE, ORACLE_META_TABLE, META_TABLE_SCHEMA_COLUMN, IS_DEPT_PIPELINE, TARGET_STORAGE_CONTAINER)
VALUES
    (SRC.IDW_LAKE_TRIGGERS_CHECK_CONTROL_KEY, SRC.IS_ACTIVE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(), SRC.ADF_PIPELINE_NAME, SRC.CONTROL_TABLE_DATABASE, SRC.CONTROL_TABLE_SCHEMA, SRC.CONTROL_TABLE_NAME, SRC.CONTROL_TABLE_TRIGGER_COLUMN_NAME, SRC.IS_PARTITION_BY_STRING_COLUMN_NAME, SRC.IS_PARTITION_BY_STRING_VALUE, SRC.IS_PARTITION_BY_DATE_COLUMN_NAME, SRC.IS_PARTITION_BY_DATE_VALUE, SRC.ORACLE_META_TABLE, SRC.META_TABLE_SCHEMA_COLUMN, SRC.IS_DEPT_PIPELINE, SRC.TARGET_STORAGE_CONTAINER)
;

DELETE FROM UTIL.IDW_LAKE_TRIGGERS_CHECK_CONTROL AS TGT
USING
(SELECT IDW_LAKE_TRIGGERS_CHECK_CONTROL_KEY, IS_ACTIVE, ADF_PIPELINE_NAME, CONTROL_TABLE_DATABASE, CONTROL_TABLE_SCHEMA, CONTROL_TABLE_NAME, CONTROL_TABLE_TRIGGER_COLUMN_NAME, IS_PARTITION_BY_STRING_COLUMN_NAME, IS_PARTITION_BY_STRING_VALUE, IS_PARTITION_BY_DATE_COLUMN_NAME, IS_PARTITION_BY_DATE_VALUE, ORACLE_META_TABLE, META_TABLE_SCHEMA_COLUMN, IS_DEPT_PIPELINE, TARGET_STORAGE_CONTAINER
