    MINUS
    SELECT IDW_LAKE_TRIGGERS_CHECK_CONTROL_KEY, IS_ACTIVE, ADF_PIPELINE_NAME, CONTROL_TABLE_DATABASE, CONTROL_TABLE_SCHEMA, CONTROL_TABLE_NAME, CONTROL_TABLE_TRIGGER_COLUMN_NAME, IS_PARTITION_BY_STRING_COLUMN_NAME, IS_PARTITION_BY_STRING_VALUE, IS_PARTITION_BY_DATE_COLUMN_NAME, IS_PARTITION_BY_DATE_VALUE, ORACLE_META_TABLE, META_TABLE_SCHEMA_COLUMN, IS_DEPT_PIPELINE, TARGET_STORAGE_CONTAINER
    FROM UTIL.IDW_LAKE_TRIGGERS_CHECK_CONTROL)
    AS SRC

